import http from'node:http';import test from'node:test';import assert from'node:assert/strict';import {RealDexNode}from'../../lib/server.mjs';import {createIdentity}from'../../lib/protocol.mjs';import {config}from'../../test/fixtures.mjs';
async function site(t){const c=config({port:0,allowedHosts:[]}),n=new RealDexNode({identity:createIdentity(),config:c});const a=await n.start({port:0,autoSync:false});c.allowedHosts.push(`127.0.0.1:${a.port}`);t.after(()=>n.close());return `http://127.0.0.1:${a.port}`;}
test('existing node serves all new modules with fixed MIME and CSP headers',async t=>{const base=await site(t);for(const name of ['spot/','spot-ui.mjs','external/math.mjs','external/observer.mjs','external/transport.mjs','external/protobuf.mjs','extended/guard.mjs','extended/http.mjs']){const r=await fetch(base+'/node/'+name);assert.equal(r.status,200,name);assert.match(r.headers.get('content-security-policy'),/frame-ancestors 'none'/);assert.equal(r.headers.get('x-content-type-options'),'nosniff');}assert.match(await(await fetch(base+'/node/')).text(),/\/node\/spot\//);});
test('observation page exposes no server POST method or arbitrary module access',async t=>{const base=await site(t);assert.equal((await fetch(base+'/node/spot/',{method:'POST',body:'{}'})).status,405);assert.equal((await fetch(base+'/node/external/sign.mjs')).status,404);assert.equal((await fetch(base+'/node/external/test/fixtures.mjs')).status,404);});
test('new observation page preserves cross-origin and host checks',async t=>{const base=await site(t);assert.equal((await fetch(base+'/node/spot/',{headers:{origin:'https://evil.example'}})).status,403);const status=await new Promise((resolve,reject)=>{const req=http.get(base+'/node/spot/',{headers:{host:'evil.example'}},r=>{r.resume();resolve(r.statusCode);});req.on('error',reject);});assert.equal(status,421);});
